with tabs[5]:
    # ---------------- PHASE 9: GIS / ADMINISTRATIVE BOUNDARY MAP ----------------
    st.markdown('<div class="section-heading">◈ GIS MAP / ADMINISTRATIVE BOUNDARIES</div>', unsafe_allow_html=True)
    st.markdown('<div class="section-sub">Karachi town boundaries · interactive administrative map · enhanced visibility</div>', unsafe_allow_html=True)
    st.markdown("""
    <div class="note-box"><div class="note-title">GEOGRAPHIC DATA STATUS</div>
    This map visualizes administrative town boundaries only. Crime data is aggregated by police range and has no town-level values or coordinates, so it cannot be validly joined to these polygons. The map is not a crime hotspot map.</div>
    """, unsafe_allow_html=True)

    import json
    import zipfile
    import io
    import shapefile

    bundled_zip = ROOT / "data" / "geo" / "Karachi Towns.shp.zip"
    uploaded_layer = st.file_uploader(
        "Optional: upload another boundary layer (Shapefile ZIP or GeoJSON)",
        type=["zip", "geojson", "json"], key="kseci_boundary_upload"
    )
    geojson = None
    source_label = "Bundled Karachi Towns shapefile"

    def read_shapefile_zip(zip_bytes):
        with zipfile.ZipFile(io.BytesIO(zip_bytes)) as archive:
            shp_name = next((n for n in archive.namelist() if n.lower().endswith(".shp")), None)
            if not shp_name:
                raise ValueError("ZIP archive does not contain a .shp file.")
            base = shp_name[:-4]
            lookup = {name.lower(): name for name in archive.namelist()}
            shx_name = lookup.get((base + ".shx").lower())
            dbf_name = lookup.get((base + ".dbf").lower())
            if not shx_name or not dbf_name:
                raise ValueError("Shapefile ZIP must include matching .shx and .dbf files.")
            reader = shapefile.Reader(
                shp=io.BytesIO(archive.read(shp_name)),
                shx=io.BytesIO(archive.read(shx_name)),
                dbf=io.BytesIO(archive.read(dbf_name)),
            )
            features = []
            for shape_record in reader.iterShapeRecords():
                geom = shape_record.shape.__geo_interface__
                props = shape_record.record.as_dict()
                features.append({"type": "Feature", "geometry": geom, "properties": props})
            if not features:
                raise ValueError("Shapefile has no polygon features.")
            return {"type": "FeatureCollection", "features": features}

    try:
        if uploaded_layer is not None:
            uploaded_bytes = uploaded_layer.getvalue()
            source_label = uploaded_layer.name
            if uploaded_layer.name.lower().endswith(".zip"):
                geojson = read_shapefile_zip(uploaded_bytes)
            else:
                geojson = json.loads(uploaded_bytes.decode("utf-8"))
        elif bundled_zip.exists():
            geojson = read_shapefile_zip(bundled_zip.read_bytes())
        else:
            st.warning("Bundled Karachi town boundaries ZIP not found at data/geo. Use the upload control above to add a Shapefile ZIP or GeoJSON.")

        if geojson is not None:
            features = geojson.get("features", []) if isinstance(geojson, dict) else []
            if geojson.get("type") != "FeatureCollection" or not features:
                st.error("Boundary layer must be a non-empty GeoJSON FeatureCollection.")
            else:
                property_keys = sorted({k for f in features for k in (f.get("properties") or {}).keys()})
                label_options = [k for k in property_keys if k.lower() in {"town", "name", "district"}]
                label_field = st.selectbox(
                    "Map label field", label_options or property_keys,
                    index=0, key="kseci_gis_label_field"
                ) if property_keys else None
                if label_field:
                    labels = [str((f.get("properties") or {}).get(label_field, f"Feature {i+1}")) for i, f in enumerate(features)]
                    display_features = features
                    selected_district = "All districts"
                    if "District" in property_keys:
                        district_names = sorted({str((f.get("properties") or {}).get("District", "Unknown")) for f in features})
                        selected_district = st.selectbox("District filter", ["All districts"] + district_names, key="kseci_gis_district")
                        if selected_district != "All districts":
                            display_features = [f for f in features if str((f.get("properties") or {}).get("District", "Unknown")) == selected_district]
                    # Phase 11: searchable town focus and visual selection
                    town_key = "Town" if "Town" in property_keys else label_field
                    town_options = sorted({str((f.get("properties") or {}).get(town_key, "Unnamed")) for f in display_features})
                    selected_town = st.selectbox(
                        "Focus on a town (optional)", ["No town selected"] + town_options,
                        key="kseci_gis_town_focus",
                    )
                    selected_feature = next(
                        (f for f in display_features if str((f.get("properties") or {}).get(town_key, "Unnamed")) == selected_town),
                None
                    ) if selected_town != "No town selected" else None
                    if selected_feature:
                        selected_props = selected_feature.get("properties") or {}
                        st.info(f"Town focus: **{selected_town}** · District: **{selected_props.get('District', 'Not specified')}**. This is an administrative selection, not a crime hotspot indicator.")
                    filtered_labels = [str((f.get("properties") or {}).get(label_field, "Unnamed")) for f in display_features]
                    hover_details = []
                    for feature, label in zip(display_features, filtered_labels):
                        props = feature.get("properties") or {}
                        town_name = str(props.get("Town", label))
                        district_name = str(props.get("District", "Not specified"))
                        hover_details.append([town_name, district_name])
                    map_geojson = {"type": "FeatureCollection", "features": display_features}
                    # Phase 15 audited: categorical district colors are administrative visualization only.
                    district_vals = [str((f.get("properties") or {}).get("District", "Unknown")) for f in display_features]
                    unique_districts = sorted(set(district_vals))
                    district_palette = ["#24A9C8", "#A78BFA", "#F2C14E", "#44C28A", "#E8799A", "#5799F5", "#FF8A5B", "#80CBC4", "#C5A3FF", "#F28FCE", """#8DD36F""", "#FFB86B"]
                    district_code = {name: i for i, name in enumerate(unique_districts)}
                    district_z = [district_code[name] for name in district_vals]
                    discrete_scale = []
                    for i, name in enumerate(unique_districts):
                        color = district_palette[i % len(district_palette)]
                        lo = i / max(len(unique_districts), 1)
                        hi = (i + 1) / max(len(unique_districts), 1)
                        discrete_scale.extend([[lo, color], [hi, color]])
                    fig_map = go.Figure(go.Choropleth(
                        geojson=map_geojson,
                        featureidkey=f"properties.{label_field}",
                        locations=filtered_labels,
                        z=district_z,
                        zmin=0, zmax=max(len(unique_districts)-1, 1),
                        colorscale=discrete_scale,
                        showscale=False,
                        customdata=hover_details,
                        marker=dict(line=dict(color="#9CEBFF", width=1.25)),
                        hovertemplate="<b>Town:</b> %{customdata[0]}<br><b>District:</b> %{customdata[1]}<extra></extra>",
                    ))
                    # Draw a brighter outline around the selected town, without changing the underlying map data.
                    if selected_feature is not None:
                        selected_label = str((selected_feature.get("properties") or {}).get(label_field, "Unnamed"))
                        selected_props = selected_feature.get("properties") or {}
                        fig_map.add_trace(go.Choropleth(
                            geojson={"type": "FeatureCollection", "features": [selected_feature]},
                            featureidkey=f"properties.{label_field}",
                            locations=[selected_label], z=[1],
                            colorscale=[[0, "rgba(242,193,78,0.22)"], [1, "rgba(242,193,78,0.22)"]],
                            showscale=False,
                            customdata=[[selected_town, str(selected_props.get("District", "Not specified"))]],
                            marker=dict(line=dict(color="#FFF1B2", width=3.2)),
                            hovertemplate="<b>SELECTED TOWN</b><br>Town: %{customdata[0]}<br>District: %{customdata[1]}<extra></extra>",
                        ))
                    fig_map.update_geos(
                        fitbounds="locations", visible=False, bgcolor="rgba(0,0,0,0)",
                        showframe=False, showcoastlines=False, showcountries=False,
                    )
                    fig_map.update_layout(
                        template="plotly_dark", height=820,
                        paper_bgcolor="rgba(0,0,0,0)", plot_bgcolor="rgba(7,15,26,0)",
                        font=dict(family="Inter", color=TEXT, size=12),
                        margin=dict(l=0, r=0, t=10, b=0),
                        hoverlabel=dict(bgcolor="#071725", bordercolor=NEON, font=dict(color=TEXT, size=13)),
                    )
                    st.plotly_chart(
                        fig_map, use_container_width=True,
                        config={"displayModeBar": True, "scrollZoom": True, "displaylogo": False,
                                "modeBarButtonsToRemove": ["lasso2d", "select2d"]},
                    )
                    col_a, col_b, col_c, col_d = st.columns(4)
                    col_a.metric("Boundary features", len(features))
                    col_b.metric("Visible features", len(display_features))
                    col_c.metric("District filter", selected_district)
                    col_d.metric("Town focus", selected_town if selected_town != "No town selected" else "None")
                    st.success(f"Boundary layer displayed · {source_label} · administrative view only")
                    # Phase 15 audited: district feature statistics, chart, and exports.
                    if "District" in property_keys:
                        district_table = pd.DataFrame({"District": district_vals}).value_counts().reset_index(name="Boundary features").sort_values("District")
                        st.markdown("#### District administrative comparison")
                        chart = px.bar(district_table, x="District", y="Boundary features", color="District", text="Boundary features")
                        chart.update_layout(template="plotly_dark", height=340, showlegend=False, paper_bgcolor="rgba(0,0,0,0)", plot_bgcolor="rgba(0,0,0,0)", margin=dict(l=10,r=10,t=20,b=10))
                        st.plotly_chart(chart, use_container_width=True)
                        st.dataframe(district_table, use_container_width=True, hide_index=True)
                        st.download_button("Download district summary CSV", district_table.to_csv(index=False).encode("utf-8-sig"), "kseci_gis_district_summary.csv", "text/csv", key="gis14_summary_csv")
                    # Export only currently visible administrative features.
                    export_table = pd.DataFrame([{k: (f.get("properties") or {}).get(k) for k in property_keys} for f in display_features])
                    st.download_button("Download visible town attributes CSV", export_table.to_csv(index=False).encode("utf-8-sig"), "kseci_gis_visible_towns.csv", "text/csv", key="gis14_visible_csv")
                    st.download_button("Download visible boundaries GeoJSON", json.dumps({"type":"FeatureCollection","features":display_features}, ensure_ascii=False).encode("utf-8"), "kseci_gis_visible_boundaries.geojson", "application/geo+json", key="gis14_geojson")
                    if "Town" in property_keys and "District" in property_keys:
                        town_table = pd.DataFrame([
                            {"Town": (f.get("properties") or {}).get("Town"), "District": (f.get("properties") or {}).get("District")}
                            for f in display_features
                        ]).drop_duplicates().sort_values(["District", "Town"])
                        with st.expander("View town / district attributes"):
                            st.dataframe(town_table, use_container_width=True, hide_index=True)
    except Exception as e:
        st.error(f"Could not load the geographic boundary layer: {e}")
        st.caption("If you uploaded a ZIP, ensure it contains .shp, .shx, and .dbf files from the same shapefile set.")

